/// What an invocation turns out to be once its aliases are expanded.
enum Resolved {
    /// Cargo has no such command, so it will say so and compile nothing.
    Unknown,
    /// A command that cannot compile, or an alias that reaches one.
    Proxy,
    /// A command that may compile: a build command, an alias that reaches one,
    /// or a subcommand external to Cargo, whose work mbx cannot see.
    Opaque,
}

/// An invocation with its aliases expanded.
struct Invocation {
    arguments: Vec<OsString>,
    resolved: Resolved,
    /// Whether the path-valued flags in `arguments` can be believed.
    ///
    /// `cargo --list` prints an alias body space-joined, so a value holding a
    /// space cannot be told apart from two arguments, and an array alias keeps
    /// such values where a string alias could not. Where the unreadable value
    /// is the one that decides which package compiles, no absent manifest can
    /// speak for the invocation.
    paths_certain: bool,
}

/// Expand an invocation's aliases and say what it turned out to be.
///
/// Nothing when the listing cannot be read, which leaves the invocation
/// unexplained and so unsafe to pass through.
fn resolve_invocation(cargo: &OsStr, arguments: &[OsString]) -> Option<Invocation> {
    let certain = |arguments: &[OsString], resolved| Invocation {
        arguments: arguments.to_vec(),
        resolved,
        paths_certain: true,
    };
    let command = super::launch::cargo_subcommand(arguments)?;
    if is_build_command(command) {
        return Some(certain(arguments, Resolved::Opaque));
    }
    // The listing describes whichever Cargo and configuration the invocation
    // selects, so it carries the same global options. `--color=never`
    // overrides `CARGO_TERM_COLOR` and `term.color`, which otherwise wrap both
    // the header and every command name in ANSI escapes and defeat the
    // plain-text parsing below.
    let (index, _) = super::launch::cargo_subcommand_at(arguments)?;
    let output = Command::new(cargo)
        .args(&arguments[..index])
        .args(["--color=never", "--list"])
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let listing = String::from_utf8_lossy(&output.stdout);
    if !listing.starts_with("Installed Commands:") {
        return None;
    }
    let entries = listing
        .lines()
        .skip(1)
        .filter_map(|line| {
            let line = line.trim();
            let end = line.find(char::is_whitespace).unwrap_or(line.len());
            (!line.is_empty()).then_some((&line[..end], line[end..].trim()))
        })
        .collect::<BTreeMap<_, _>>();
    let mut current = command.to_owned();
    let mut invocation = arguments.to_vec();
    let mut paths_certain = true;
    for _ in 0..32 {
        let Some(description) = entries.get(current.as_str()) else {
            return Some(Invocation {
                arguments: invocation,
                resolved: Resolved::Unknown,
                paths_certain,
            });
        };
        let Some(alias) = description.strip_prefix("alias: ") else {
            return Some(Invocation {
                arguments: invocation,
                resolved: Resolved::Opaque,
                paths_certain,
            });
        };
        let expansion = alias.split_whitespace().collect::<Vec<_>>();
        if expansion.is_empty() {
            return None;
        }
        paths_certain &= path_words_intact(&expansion);
        // Substitute the expansion for the alias and keep the rest of the
        // command line. The expanded name alone would hide a `--path` from
        // either place it can appear: the alias body, or the arguments after
        // it. Both make an install compile a local package rather than fetch
        // one.
        let (index, _) = super::launch::cargo_subcommand_at(&invocation)?;
        invocation.splice(
            index..index + 1,
            expansion.iter().copied().map(OsString::from),
        );
        if cargo_proxy_passthrough(&invocation) {
            return Some(Invocation {
                arguments: invocation,
                resolved: Resolved::Proxy,
                paths_certain,
            });
        }
        // An alias body may lead with global options, which name no command
        // and appear in no listing. What it runs is the command the expanded
        // line now names, so read that rather than the body's first word.
        let next = super::launch::cargo_subcommand(&invocation)?.to_owned();
        if is_build_command(&next) {
            return Some(Invocation {
                arguments: invocation,
                resolved: Resolved::Opaque,
                paths_certain,
            });
        }
        current = next;
    }
    None
}

/// Whether an expansion's path arguments survived the listing intact.
///
/// `cargo --list` prints an alias body space-joined, so a value holding a
/// space arrives as several words and names some prefix of the real path. The
/// split shows itself in the word following the value: an alias's remaining
/// arguments are flags, and `install` takes no positional package beside
/// `--path`, so a bare word there is the tail of a value this cannot put back
/// together.
///
/// Every argument that decides which manifest Cargo reads is checked, which
/// is the directory options as much as the path ones: `manifest_in_scope`
/// starts its search from `-C`, so a `-C` it misreads sends the search
/// somewhere Cargo will not go.
fn path_words_intact(words: &[&str]) -> bool {
    let mut index = 0;
    while index < words.len() {
        let word = words[index];
        let separate = matches!(word, "--path" | "--manifest-path" | "-C" | "--directory");
        let attached = ["--path=", "--manifest-path=", "--directory="]
            .iter()
            .any(|flag| word.starts_with(flag))
            || (word.starts_with("-C") && word.len() > 2);
        let after = if separate {
            index + 2
        } else if attached {
            index + 1
        } else {
            index += 1;
            continue;
        };
        if words.get(after).is_some_and(|word| !word.starts_with('-')) {
            return false;
        }
        index = after;
    }
    true
}

fn is_build_command(command: &str) -> bool {
    matches!(
        command,
        "build"
            | "b"
            | "check"
            | "c"
            | "test"
            | "t"
            | "run"
            | "r"
            | "bench"
            | "doc"
            | "d"
            | "rustc"
            | "rustdoc"
            | "clippy"
            | "fix"
    )
}

/// What to do with an invocation whose roots probe failed.
pub(super) enum FailedProbe {
    /// Roots recovered from the expanded invocation: manage the build.
    Roots(Box<super::cargo::Roots>),
    /// Hand the invocation to Cargo as it was typed.
    Passthrough,
    /// Refuse it: the build storage cannot be verified.
    Reject,
}

/// Decide what a failed roots probe leaves the caller able to do.
///
/// The listing this reads is one Cargo process, so the whole decision is made
/// here rather than once per question.
pub(super) fn failed_probe(
    cargo: &OsStr,
    arguments: &[OsString],
    target_dir_env: Option<&OsStr>,
) -> FailedProbe {
    // An alias can name a manifest that the command line does not, so expand
    // it before reading the invocation: `i = "install --path /project"`
    // compiles a local package from a directory that has none of its own.
    let invocation = resolve_invocation(cargo, arguments);
    // The first probe asked about the alias's own name and got nothing back.
    // Ask again as Cargo will read it: the roots belong to the package the
    // expansion names, though the child still receives the command line as it
    // was typed, since Cargo expands the alias itself.
    if let Some(resolved) = &invocation
        && resolved.paths_certain
        && resolved.arguments != arguments
        && let Ok(expanded) = super::strings(&resolved.arguments)
        && let Some(roots) = super::cargo::cargo_roots(cargo, &expanded, target_dir_env)
    {
        return FailedProbe::Roots(Box::new(roots));
    }
    // A single-file `-Zscript` package compiles without a manifest, so absent
    // manifests cannot speak for these the way they do for everything else.
    // An alias body carries its own options, so the expansion answers this as
    // much as the command line does.
    let unstable = |arguments: &[OsString]| {
        arguments
            .iter()
            .any(|argument| argument.to_string_lossy().starts_with("-Z"))
    };
    let scripted = unstable(arguments)
        || invocation
            .as_ref()
            .is_some_and(|resolved| unstable(&resolved.arguments));
    if !scripted && metadata_failure_passthrough(invocation.as_ref()) {
        return FailedProbe::Passthrough;
    }
    FailedProbe::Reject
}

/// Preserve invocations outside a project, non-build aliases, and
/// unknown-command diagnostics without allowing failed metadata to launch a
/// build alias or an external Cargo command inside one.
fn metadata_failure_passthrough(invocation: Option<&Invocation>) -> bool {
    let Some(invocation) = invocation else {
        return false;
    };
    // No manifest where Cargo looks for one means no package to build and no
    // target directory to place, so the probe failed because Cargo has nothing
    // to do here rather than because its storage is unverifiable. This is the
    // ordinary way to reach a failed probe: an external subcommand such as
    // `cargo binstall` run outside a project, where Cargo itself would not
    // have read a manifest either. An alias whose own path arguments came back
    // unreadable is the exception: Cargo can still reach a manifest that this
    // cannot see, so it answers below on what the command is instead.
    if invocation.paths_certain
        && let Ok(strings) = super::strings(&invocation.arguments)
        && let Ok(working_dir) = std::env::current_dir()
        && !mbx_cache_cargo::manifest_in_scope(&strings, &working_dir)
    {
        return true;
