    std::fs::write(f.outside.join(".cargo/config"), format!("[alias]\nb={install}\n")).unwrap();
    for shim in [false, true] {
        rejected(f.command(shim).arg("b").env("REJECT_METADATA", "1").output().unwrap());
    }
}

