#[derive(serde::Deserialize)]
#[serde(untagged)]
enum Alias {
    String(String),
    Array(Vec<String>),
}

impl Alias {
    fn arguments(self) -> Vec<OsString> {
        match self {
            Self::String(value) => value.split_whitespace().map(OsString::from).collect(),
            Self::Array(value) => value.into_iter().map(OsString::from).collect(),
        }
    }
